#!/bin/bash
set -eo pipefail
export PYTHONDONTWRITEBYTECODE=1
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python - <<'PYREMOTE'
from pathlib import Path
import json,hashlib,base64,subprocess,importlib.util,fcntl,os,datetime,re
r=Path('/data1/home/sunyiq/hydrol85935_temporal_attempts/hpc_v009_001/hydrol85935_temporal_persistence_20261011_001')
c=r/'control/queue_priority_20261014_001'
d=r/'control/infeasible_recovery_20261015_001'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,v):
 with p.open('x') as f:json.dump(v,f,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
def run(args):return subprocess.run(args,capture_output=True,text=True,timeout=90,check=True)
assert not d.exists(),'New attempt directory already exists; inspect instead of replaying'
assert sha(c/'queue_priority.py')=='a3de8ee97281cb5b1ff7ab745bd8b4506abf3da932d35869b08eec3d0631fe6e'
reg=read(c/'watcher_registration.json');p=Path('/proc')/str(reg['pid'])
assert not (p.exists() and (p/'stat').read_text().split()[21]==reg['proc_start_ticks'] and (p/'cmdline').read_bytes().split(b'\0')[:-1]==[v.encode() for v in reg['command']]),'Old coordinator is active'
assert read(c/'status.json')['status']=='NEEDS_RECONCILIATION'
assert not (c/'parent_released.json').exists()
with (c/'coordinator.lock').open('a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 s=importlib.util.spec_from_file_location('frozen_base',r/'versions/v002/advance.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
 assert m.verify_bundle(r)=='94041e68d4a8242f1dbb70d26db37b2562dbe915c5e36a8741af97d6ec63406f'
 subs=[read(p) for p in (r/'control/submissions').glob('*.json') if not p.name.endswith('.attempt.json')]
 assert {v['stage'] for v in subs}=={'preflight','main_s100'} and {v['job_id'] for v in subs}=={241345,242488}
 assert sha(r/'control/submissions/main_s100.sbatch')=='949b77e8f3e0c0020054e4c6f84e3c68d0746992ed1ae3ecc71a2f65f7c7b458'
 rows=[line.split('|') for line in run(['squeue','-r','-h','-u','sunyiq','-o','%i|%T|%r|%C|%b']).stdout.splitlines()]
 held=set(read(c/'applied.json')['held_parent_ids']);selected={v[0]:v for v in rows if v[0] in held}
 assert len(held)==125 and set(selected)==held and all(v[1:3]==['PENDING','JobHeldUser'] for v in selected.values())
 active=[v for v in rows if v[0].split('_')[0]=='242488' and v[1] in {'RUNNING','COMPLETING'}]
 assert len(active)<=1 and all(v[3]=='4' and v[4] in {'gpu:1','gres:gpu:1'} for v in active)
 payload={"diagnose_infeasible.py": {"sha256": "a484f3f65e8162fc459133261275dcf7da70b71e95c8906a52221c5022a70b78", "base64": ""}, "diagnostic.sbatch": {"sha256": "d13ce83e4b4a0eb3f1a2d840024cb92e22f3f5dfb0c15a6a4a9b3ca9df43cd75", "base64": ""}}
 d.mkdir()
 for name,item in payload.items():
  assert name in {'diagnose_infeasible.py','diagnostic.sbatch'}
  raw=base64.b64decode(item['base64']);assert hashlib.sha256(raw).hexdigest()==item['sha256']
  with (d/name).open('xb') as f:f.write(raw)
 run(['bash','-n',str(d/'diagnostic.sbatch')])
 write(d/'deployment.json',{'files':{k:v['sha256'] for k,v in payload.items()},'source_root':str(r),'old_status':read(c/'status.json'),'old_watcher_registration':reg,'old_array':242488,'parent_held_count':125,'old_records_modified':False,'scientific_rules_changed':False})
 attempt={'stage':'bounds_diagnostic','dependency':'afterany:242488','gpus':1,'cpus':4,'script_sha256':sha(d/'diagnostic.sbatch'),'code_sha256':sha(d/'diagnose_infeasible.py'),'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 write(d/'submission.attempt.json',attempt)
 result=subprocess.run(['sbatch',str(d/'diagnostic.sbatch')],capture_output=True,text=True,timeout=120)
 write(d/'submission.output.json',{'returncode':result.returncode,'stdout':result.stdout,'stderr':result.stderr})
 ids=re.findall(r'(?m)^Submitted batch job ([0-9]+)$',result.stdout)
 if result.returncode or len(ids)!=1:raise RuntimeError('Unconfirmed diagnostic submission; do not replay')
 attempt.update(job_id=int(ids[0]),status='SUBMITTED');write(d/'submission.json',attempt)
 state=run(['scontrol','show','job','-o',str(ids[0])]).stdout
 write(d/'scheduler_identity.json',{'job_id':ids[0],'scontrol':state})
 assert 'NumCPUs=4' in state and 'TresPerNode=gpu:1' in state and 'Command='+str(d/'diagnostic.sbatch') in state and 'WorkDir='+str(d) in state
 assert 'Dependency=afterany:242488' in state or 'Dependency=(null)' in state
 print('DIAGNOSTIC_REGISTERED '+json.dumps({'receipt':attempt,'scheduler':state,'parent_jobs_modified':False,'old_coordinator_restarted':False}),flush=True)
PYREMOTE
